// The language list itself, with no browser code, so Node scripts (scripts/build-cheatsheet.ts) can read
// it; the site imports it through ./languages.ts.

// The languages (and dialects) the site can translate into, picked on the Settings page. Each one needs
// its own Cheatsheet data, generated by scripts/build-cheatsheet.ts (which reads this list), and an entry
// in the backend's TARGETS (supabase/functions/_shared/journal.ts). Only what which-dialect can translate
// English into belongs here: Vietnamese's three dialects, and Spanish by country (since 2026-10-29).

export type TargetLanguage = {
  // Saved in settings and used in data file names: "vi-Southern" → public/cheatsheet/top-100.vi-Southern.json.
  id: string
  // which-dialect's language code and region.
  code: string
  region?: string
  // "Vietnamese" and "Southern": the Settings page groups dialects under their language.
  language: string
  dialect?: string
  // How the rest of the site names it: "Southern Vietnamese".
  label: string
  // What which-dialect has for the language beyond words: a pronoun table (the Cheatsheet's "who are you
  // talking to?", the journal's pronoun check) and sentence frames (the journal's Frames tool).
  pronouns?: boolean
  frames?: boolean
  // The Settings example of a regional word ("Northern “lợn” → Southern “heo”").
  regionalExample: string
}

const VI = { code: 'vi', language: 'Vietnamese', pronouns: true, frames: true, regionalExample: 'Northern “lợn” → Southern “heo”' }
// Spanish: sentence frames (since which-dialect-es 0.2.3), no pronoun table yet. Countries with the most
// region-tagged words, plus Latin America as a whole (any of its countries' words).
const ES = { code: 'es', language: 'Spanish', frames: true, regionalExample: 'Spain “coche” → Mexico “carro”' }

export const TARGET_LANGUAGES: TargetLanguage[] = [
  { ...VI, id: 'vi-Southern', region: 'Southern', dialect: 'Southern', label: 'Southern Vietnamese' },
  { ...VI, id: 'vi-Central', region: 'Central', dialect: 'Central', label: 'Central Vietnamese' },
  { ...VI, id: 'vi-Northern', region: 'Northern', dialect: 'Northern', label: 'Northern Vietnamese' },
  { ...ES, id: 'es-Latin-America', region: 'Latin America', dialect: 'Latin America', label: 'Latin American Spanish' },
  { ...ES, id: 'es-Mexico', region: 'Mexico', dialect: 'Mexico', label: 'Mexican Spanish' },
  { ...ES, id: 'es-Spain', region: 'Spain', dialect: 'Spain', label: 'Spanish from Spain' },
  { ...ES, id: 'es-Argentina', region: 'Argentina', dialect: 'Argentina', label: 'Argentine Spanish' },
  { ...ES, id: 'es-Colombia', region: 'Colombia', dialect: 'Colombia', label: 'Colombian Spanish' },
]
